 "content": "from collections import Counter


def transform(grid):
    """Map the dominant input color to the sparse color; erase sparse cells."""
    counts = Counter(value for row in grid for value in row)
    if len(counts) != 2:
        raise ValueError("Expected a two-color grid")
    dominant, sparse = counts.most_common()[0][0], counts.most_common()[1][0]
    return [[sparse if value == dominant else 0 for value in row] for row in grid]
